const parts = msg.split(' ');
let numeroCliente = (parts[1] || '').trim();

// Garante que o número tem @s.whatsapp.net
if (numeroCliente && !numeroCliente.includes('@')) {
  numeroCliente = numeroCliente + '@s.whatsapp.net';
}

return [{ json: { numeroCliente } }];

