const items = $input.all();
let isHuman = false;

try {
  if (items.length > 0) {
    const resp = items[0]?.json;
    if (resp) {
      // n8n HTTP Request expande arrays: cada elemento vira item separado
      // resp é diretamente { status: 'humano' }, não um array
      if (resp.status === 'humano') {
        isHuman = true;
      }
      // Compatibilidade caso resp ainda seja array
      else if (Array.isArray(resp) && resp.length > 0 && resp[0].status === 'humano') {
        isHuman = true;
      }
    }
  }
} catch(e) {
  isHuman = false;
}

// Preserva os dados originais da mensagem
const dadosOriginais = $('Dados').item.json;
return [{ json: { ...dadosOriginais, isHuman } }];

const items = $input.all();
const msg = (items[0]?.json?.message || '').toLowerCase().trim();

const palavrasHandoff = [
  'falar com humano',
  'falar com atendente',
  'atendente humano',
  'atendimento humano',
  'quero humano',
  'quero um atendente',
  'quero falar com atendente',
  'falar com alguém',
  'falar com alguem',
  'pessoa real',
  'falar com pessoa',
  'me passa para humano',
  'me transfere para atendente',
  '/humano',
  'quero atendimento humano',
  'preciso de um atendente'
];

// Opcao 4 — Treinamento Pratico CD-CL (vai direto para handoff)
const opcao4 = msg === '4' || msg === '4.' ||
  msg.includes('treinamento pratico') || msg.includes('treinamento prático') ||
  msg.includes('treino pratico') || msg.includes('treino prático');

// Opcao 6 — Falar com atendente humano (vai direto para handoff)
const opcao6 = msg === '6' || msg === '6.' ||
  msg.includes('opção 6') || msg.includes('opcao 6');

const handoffDetectado = palavrasHandoff.some(p => msg.includes(p)) || opcao4 || opcao6;

// Tipo para personalizar a mensagem ao atendente
let handoffTipo = 'padrao';
if (opcao4) handoffTipo = 'treinamento_pratico';
if (opcao6) handoffTipo = 'opcao6';

return items.map(item => ({
  json: { ...item.json, handoffDetectado, handoffTipo }
}));

